(3157903, 443038, 27482, '<td valign="top">Sorry but not really digging the fisheye effect on this shot, all I can say is I would have voted higher without it.</td>', 'Sorry but not really digging the fisheye effect on this shot, all I can say is I would have voted higher without it.', '2006-12-29 00:04:15.000000', NULL, 1),
(3157905, 443365, 27482, '<td valign="top">Sorry, not digging the sky in this shot, strong artefacting or wierd spots that I honestly don´t care for.  Composition is not bad but could be a lot better, a little too much foreground for my taste and nowhere really for the eyes to stop and rest.</td>', 'Sorry, not digging the sky in this shot, strong artefacting or wierd spots that I honestly don´t care for.  Composition is not bad but could be a lot better, a little too much foreground for my taste and nowhere really for the eyes to stop and rest.', '2006-12-29 00:05:16.000000', NULL, 1),
(3157906, 443913, 36470, '<td valign="top">Outstanding photo.  I am sure this would make you plenty of money through a stock agency.  Love it.</td>', 'Outstanding photo.  I am sure this would make you plenty of money through a stock agency.  Love it.', '2006-12-29 00:05:18.000000', NULL, 1),
