(3158508, 442276, 18799, '<td valign="top">I don''t get what the border is intending to do, IMO it''s just a distraction.  Other than that, I like the photo and did not deduct for the border.</td>', 'I don''t get what the border is intending to do, IMO it''s just a distraction.  Other than that, I like the photo and did not deduct for the border.', '2006-12-29 03:54:12.000000', NULL, 1),
(3158509, 443401, 18799, '<td valign="top">Nice idea.  I don''t care too much for the halos around the trees though. 6</td>', 'Nice idea.  I don''t care too much for the halos around the trees though. 6', '2006-12-29 03:56:25.000000', NULL, 1),
(3158510, 443509, 18799, '<td valign="top">Terrific photo.  One nit though, I wish whatever that red thing is in the foreground wasn''t there.</td>', 'Terrific photo.  One nit though, I wish whatever that red thing is in the foreground wasn''t there.', '2006-12-29 03:58:04.000000', NULL, 1),
(3158537, 442686, 52439, '<td valign="top">You managed to keep the lighting and the exposures similar all the way through, which to me is the hardest bit when doing one of these.<br/>Well done.</td>', 'You managed to keep the lighting and the exposures similar all the way through, which to me is the hardest bit when doing one of these.Well done.', '2006-12-29 04:40:48.000000', NULL, 1),
(3158538, 442808, 52439, '<td valign="top">It shows great technique and a good idea but i''d have liked something abit more interesting, there isn''t much subject matter really.</td>', 'It shows great technique and a good idea but i''d have liked something abit more interesting, there isn''t much subject matter really.', '2006-12-29 04:41:38.000000', NULL, 1),
(3158539, 443620, 52439, '<td valign="top">Like the tones, could do with being slightly dodged in some areas just to bring out a bit more detail.</td>', 'Like the tones, could do with being slightly dodged in some areas just to bring out a bit more detail.', '2006-12-29 04:42:17.000000', NULL, 1),
(3158540, 443427, 52439, '<td valign="top">Impressive, seems just ever so slightly underexposed to me though?</td>', 'Impressive, seems just ever so slightly underexposed to me though?', '2006-12-29 04:42:43.000000', NULL, 1),
(3158541, 443891, 52439, '<td valign="top">Very nice b/w, love the tones.<br/>Subject took a minute to translate to the challenge but i got there in the end.<br/>:P</td>', 'Very nice b/w, love the tones.Subject took a minute to translate to the challenge but i got there in the end.:P', '2006-12-29 04:43:38.000000', NULL, 1),
