(3158957, 443646, 49109, '<td valign="top">structures in the sky are a bit too prominent for my taste. otherwise well done, you created a very uncomfortable mood</td>', 'structures in the sky are a bit too prominent for my taste. otherwise well done, you created a very uncomfortable mood', '2006-12-29 09:19:11.000000', NULL, 1),
(3158964, 442808, 49109, '<td valign="top">nice idea, well processed. would be even more harsh at opening times</td>', 'nice idea, well processed. would be even more harsh at opening times', '2006-12-29 09:21:44.000000', NULL, 1),
(3158972, 442771, 49109, '<td valign="top">background is much too bright, DOF of surface doesn''t match DOF of "moon". Also, there should be a "martian" red tint</td>', 'background is much too bright, DOF of surface doesn''t match DOF of "moon". Also, there should be a "martian" red tint', '2006-12-29 09:24:49.000000', NULL, 1),
(3158977, 441885, 66597, '<td valign="top">This photo is of National Geographic quality. I nearly started crying when I opened it. The expressions are incredibly haunting, yet hopeful at the same time. The light is beautiful, the composition is astounding and the word "ghost" in the graffiti makes this work of art even more poignant. This may be my favorite photo of all time on this site.</td>', 'This photo is of National Geographic quality. I nearly started crying when I opened it. The expressions are incredibly haunting, yet hopeful at the same time. The light is beautiful, the composition is astounding and the word "ghost" in the graffiti makes this work of art even more poignant. This may be my favorite photo of all time on this site.', '2006-12-29 09:26:36.000000', NULL, 1),
(3158986, 443548, 45790, '<td valign="top">Scarier than the Wizard of Oz. Did that giant cat just finish his meal?</td>', 'Scarier than the Wizard of Oz. Did that giant cat just finish his meal?', '2006-12-29 09:31:43.000000', NULL, 1),
(3158991, 443038, 45790, '<td valign="top">Love the humor. Good use of fisheye lens. I''m munching on some See''s Peanut Brittle now (true!).</td>', 'Love the humor. Good use of fisheye lens. I''m munching on some See''s Peanut Brittle now (true!).', '2006-12-29 09:35:33.000000', NULL, 1),
(3159010, 443277, 66597, '<td valign="top">I love the graininess, use of selective desat, and environmental message in this. Great entry. 9.</td>', 'I love the graininess, use of selective desat, and environmental message in this. Great entry. 9.', '2006-12-29 09:43:44.000000', NULL, 1),
(3159018, 442529, 33515, '<td valign="top">Great detail in the clouds but the scene seems flat when it comes to colors. Looks like a stormy day to be on the beach!</td>', 'Great detail in the clouds but the scene seems flat when it comes to colors. Looks like a stormy day to be on the beach!', '2006-12-29 09:45:31.000000', NULL, 1),
(3159020, 443594, 36606, '<td valign="top">very nice shot. Great idea</td>', 'very nice shot. Great idea', '2006-12-29 09:45:39.000000', NULL, 1),
