(3159027, 443498, 33515, '<td valign="top">The ducks don''t seem to fit to the photo, it feels like they were layered in from another photo.</td>', 'The ducks don''t seem to fit to the photo, it feels like they were layered in from another photo.', '2006-12-29 09:47:09.000000', NULL, 1),
(3159028, 442359, 63398, '<td valign="top">A little over-processed for my tastes, but a nice entry nonetheless.</td>', 'A little over-processed for my tastes, but a nice entry nonetheless.', '2006-12-29 09:47:41.000000', NULL, 1),
(3159039, 443509, 63398, '<td valign="top">Nice entry.....definitely vast desolation exhibiting a harsh environment.</td>', 'Nice entry.....definitely vast desolation exhibiting a harsh environment.', '2006-12-29 09:51:07.000000', NULL, 1),
(3159042, 441846, 45790, '<td valign="top">Very scary. Don''t know what the black splatter is about, but it does make things creepier.</td>', 'Very scary. Don''t know what the black splatter is about, but it does make things creepier.', '2006-12-29 09:51:59.000000', NULL, 1),
