(3159058, 442842, 45790, '<td valign="top">Very effective! Great composition. The sun shining in the distance (that will never be reached) through the foreboding clouds is a big plus.</td>', 'Very effective! Great composition. The sun shining in the distance (that will never be reached) through the foreboding clouds is a big plus.', '2006-12-29 09:55:42.000000', NULL, 1),
(3159059, 443276, 45790, '<td valign="top">Doing this in blue I expect really improved this over the color original -- it''s really cold and desolate. Effective!</td>', 'Doing this in blue I expect really improved this over the color original -- it''s really cold and desolate. Effective!', '2006-12-29 09:55:48.000000', NULL, 1),
(3159060, 443555, 63398, '<td valign="top">Awesome! Poignant, troubling, provocative......stellar entry! I see it''s in my home state of Pennsylvania, too!</td>', 'Awesome! Poignant, troubling, provocative......stellar entry! I see it''s in my home state of Pennsylvania, too!', '2006-12-29 09:56:32.000000', NULL, 1),
(3159064, 443749, 63398, '<td valign="top">Nice pic......definitely a harsh environment!</td>', 'Nice pic......definitely a harsh environment!', '2006-12-29 09:58:01.000000', NULL, 1),
