(3159094, 443599, 6349, '<td valign="top">My favorite in the challenge.  Great composition with lines and colors.  A new look at something familiar and a harsh environment I am very familiar with.  Excellent title as well.  10 and favorite.</td>', 'My favorite in the challenge.  Great composition with lines and colors.  A new look at something familiar and a harsh environment I am very familiar with.  Excellent title as well.  10 and favorite.', '2006-12-29 10:06:04.000000', NULL, 1),
(3159095, 441839, 6349, '<td valign="top">One of my favorites in the challenge although I must admit that I might prefer the shot on the left alone even though I do appreciate the presentation.</td>', 'One of my favorites in the challenge although I must admit that I might prefer the shot on the left alone even though I do appreciate the presentation.', '2006-12-29 10:06:49.000000', NULL, 1),
(3159096, 442686, 63398, '<td valign="top">That''s just scary!!!!!! Better you than me!</td>', 'That''s just scary!!!!!! Better you than me!', '2006-12-29 10:06:54.000000', NULL, 1),
