(3159800, 442590, 66201, '<td valign="top">Not sure if there is high noise, oversharpening, or just plenty of lichen on the rocks... Great leading lines though.</td>', 'Not sure if there is high noise, oversharpening, or just plenty of lichen on the rocks... Great leading lines though.', '2006-12-29 14:14:07.000000', NULL, 1),
(3159811, 442700, 31829, '<td valign="top">This would be much better without the fake lightning.  A 7 from me though.</td>', 'This would be much better without the fake lightning.  A 7 from me though.', '2006-12-29 14:18:03.000000', NULL, 1),
(3159812, 443625, 55838, '<td valign="top">Back to bump up to an 8.  The meteor makes the shot.  It looks like a poster in a "head-shop" :)  Cool.</td>', 'Back to bump up to an 8.  The meteor makes the shot.  It looks like a poster in a "head-shop" :)  Cool.', '2006-12-29 14:18:14.000000', NULL, 1),
(3159819, 442700, 55838, '<td valign="top">Gorgeous!!  One of my top picks.  Love the contrast and the fluffy mean clouds but you know it''s all about the lightning baby!  Awesome job.  Back to bump you up to 9.</td>', 'Gorgeous!!  One of my top picks.  Love the contrast and the fluffy mean clouds but you know it''s all about the lightning baby!  Awesome job.  Back to bump you up to 9.', '2006-12-29 14:19:20.000000', NULL, 1),
(3159824, 443649, 55838, '<td valign="top">HAHAHA that is so gross and cool!  :)  You just have to dig in and get your elbows dirty...that''s what I always say!!  If you are ever in our neighborhood stop on by....oh and bring your cleaning supplies!  Fun shot and done so very well.  Back to bump you up to 8.</td>', 'HAHAHA that is so gross and cool!  :)  You just have to dig in and get your elbows dirty...that''s what I always say!!  If you are ever in our neighborhood stop on by....oh and bring your cleaning supplies!  Fun shot and done so very well.  Back to bump you up to 8.', '2006-12-29 14:21:20.000000', NULL, 1),
(3159825, 443917, 55838, '<td valign="top">Hey!!  You found my childhood home!!  If only I were kidding...</td>', 'Hey!!  You found my childhood home!!  If only I were kidding...', '2006-12-29 14:21:51.000000', NULL, 1),
(3159826, 443613, 55838, '<td valign="top">HAHAHAHA!!!  Harsh INDEED!  I feel your pain!  Great idea and very nice shot.  Back again...bumping up to 8.</td>', 'HAHAHAHA!!!  Harsh INDEED!  I feel your pain!  Great idea and very nice shot.  Back again...bumping up to 8.', '2006-12-29 14:22:07.000000', NULL, 1),
(3159827, 443646, 62187, '<td valign="top">Wow...very, very nice...I mean harsh! Wow...I love it. I think with expert editing you could have cloned the top-most wire out and had a photo worth an eleven. I do regret to tell you that I don''t or rarely vote in challenges I enter which I do have a submission for in this challenge. If I were voting, I''d give you a 10 - your photo would be my pick for the blue ribbon. I will say, I''m saving your photo to favs and best of luck to you!</td>', 'Wow...very, very nice...I mean harsh! Wow...I love it. I think with expert editing you could have cloned the top-most wire out and had a photo worth an eleven. I do regret to tell you that I don''t or rarely vote in challenges I enter which I do have a submission for in this challenge. If I were voting, I''d give you a 10 - your photo would be my pick for the blue ribbon. I will say, I''m saving your photo to favs and best of luck to you!', '2006-12-29 14:22:27.000000', NULL, 1),
(3159831, 443717, 55838, '<td valign="top">Wonderful shot.  Very well captured and a harsh environment indeed.  Tugs at my heart.  Back to bump you up to 8.</td>', 'Wonderful shot.  Very well captured and a harsh environment indeed.  Tugs at my heart.  Back to bump you up to 8.', '2006-12-29 14:23:14.000000', NULL, 1),
(3159834, 442842, 55838, '<td valign="top">Great light rays and cracked ground.  C''mon buddy...keep going into the light!  :)  Back to bump you up to 8.</td>', 'Great light rays and cracked ground.  C''mon buddy...keep going into the light!  :)  Back to bump you up to 8.', '2006-12-29 14:25:13.000000', NULL, 1),
(3159842, 443415, 55838, '<td valign="top">Awesome capture!  Love the soft whiteness of the picture - feels cold. The eagle is so cool - I love the angle he is on.  Back to bump you up to 8.</td>', 'Awesome capture!  Love the soft whiteness of the picture - feels cold. The eagle is so cool - I love the angle he is on.  Back to bump you up to 8.', '2006-12-29 14:27:01.000000', NULL, 1),
(3159846, 441885, 55838, '<td valign="top">Wonderful image.  Perfect for the challenge and emotive too.  One of my favorites for the challenge.  Back to bump you up to 9.  VERY well done.</td>', 'Wonderful image.  Perfect for the challenge and emotive too.  One of my favorites for the challenge.  Back to bump you up to 9.  VERY well done.', '2006-12-29 14:28:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3159857, 443365, 66201, '<td valign="top">I really like this, but I think it''s erred on the side of high contrast...it could have spoken for itself without such heavy processsing. But I give it an 8.</td>', 'I really like this, but I think it''s erred on the side of high contrast...it could have spoken for itself without such heavy processsing. But I give it an 8.', '2006-12-29 14:31:22.000000', NULL, 1),
(3159858, 443830, 55838, '<td valign="top">Great shot.  I love the silhouettes and the fog.  Feels huge and cold.  My eyes would like to see a little more contrast within the image - maybe brighten the lights and darken the silhouettes - just my opinion.  Great job and back to bump you up to 8.</td>', 'Great shot.  I love the silhouettes and the fog.  Feels huge and cold.  My eyes would like to see a little more contrast within the image - maybe brighten the lights and darken the silhouettes - just my opinion.  Great job and back to bump you up to 8.', '2006-12-29 14:31:51.000000', NULL, 1),
(3159887, 442842, 66201, '<td valign="top">I love this idea,and the colour tones and the composition. In terms of processing though, the body seems to me floating a few inches off the ground which is "unsettling" (no pun intended).</td>', 'I love this idea,and the colour tones and the composition. In terms of processing though, the body seems to me floating a few inches off the ground which is "unsettling" (no pun intended).', '2006-12-29 14:43:12.000000', NULL, 1),
