(3165298, 443599, 68685, '<td valign="top">harsh enviroment?</td>', 'harsh enviroment?', '2006-12-31 21:13:05.000000', NULL, 1),
(3165309, 441885, 47933, '<td valign="top">This is a fave in the challenge for me. Like another entry I saw, it speaks the proverbial "volumes". While you certainly didn''t use the new rules - you didn''t have to. Everything is so dramatic in this image, from the writing on the door facing to the curtains halfway hanging to the scar on dad''s eyebrow, to the beautiful smiling mother with the unbuttoned pants holding her precious infant. This is definitely a harsh environment at it''s finest (worst) and deserves a much better score than I''m sure it will get. Thank you for submitting such a powerful picture.</td>', 'This is a fave in the challenge for me. Like another entry I saw, it speaks the proverbial "volumes". While you certainly didn''t use the new rules - you didn''t have to. Everything is so dramatic in this image, from the writing on the door facing to the curtains halfway hanging to the scar on dad''s eyebrow, to the beautiful smiling mother with the unbuttoned pants holding her precious infant. This is definitely a harsh environment at it''s finest (worst) and deserves a much better score than I''m sure it will get. Thank you for submitting such a powerful picture.', '2006-12-31 21:14:29.000000', NULL, 1),
(3165313, 443380, 68685, '<td valign="top">a re-look, looks even worse</td>', 'a re-look, looks even worse', '2006-12-31 21:14:58.000000', NULL, 1),
(3165326, 443594, 68685, '<td valign="top">The color treatment is good, but somehow I can''t explain why a naked lady is in a used tire and that''s a harsh enviroment...</td>', 'The color treatment is good, but somehow I can''t explain why a naked lady is in a used tire and that''s a harsh enviroment...', '2006-12-31 21:17:39.000000', NULL, 1),
