(3167030, 443913, 30982, '<td valign="top">A lovely seaside shot - classic.  Looks quite inviting rather than harsh, though.</td>', 'A lovely seaside shot - classic.  Looks quite inviting rather than harsh, though.', '2007-01-01 09:12:29.000000', NULL, 1),
(3167033, 443548, 30982, '<td valign="top">Heh - what a suprising picture.  When you first look, it''s a lovely enchanted forest... then the duck appears.. then the cat.</td>', 'Heh - what a suprising picture.  When you first look, it''s a lovely enchanted forest... then the duck appears.. then the cat.', '2007-01-01 09:13:40.000000', NULL, 1),
(3167034, 443357, 30982, '<td valign="top">Definitely creates the impression of "harsh"!</td>', 'Definitely creates the impression of "harsh"!', '2007-01-01 09:14:21.000000', NULL, 1),
(3167036, 443751, 30982, '<td valign="top">I do like the processing you used here - almost an ethereal quality.</td>', 'I do like the processing you used here - almost an ethereal quality.', '2007-01-01 09:16:52.000000', NULL, 1),
(3167038, 443816, 30982, '<td valign="top">Love the light - really nice how the little jutty is lit and the background is in shadow and monotone.</td>', 'Love the light - really nice how the little jutty is lit and the background is in shadow and monotone.', '2007-01-01 09:17:52.000000', NULL, 1),
(3167040, 443069, 30982, '<td valign="top">Nice DOF, nice toning.  I''m a wee bit tired of guns, but that''s a personal opinion.</td>', 'Nice DOF, nice toning.  I''m a wee bit tired of guns, but that''s a personal opinion.', '2007-01-01 09:18:19.000000', NULL, 1),
