(3167043, 441504, 30982, '<td valign="top">Quite clever and very well done.</td>', 'Quite clever and very well done.', '2007-01-01 09:19:17.000000', NULL, 1),
(3167045, 442276, 30982, '<td valign="top">Beautiful shot - would make a lovely print.</td>', 'Beautiful shot - would make a lovely print.', '2007-01-01 09:20:12.000000', NULL, 1),
