INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3167067, 442521, 30982, '<td valign="top">Excellent post processing and a nicely seen and captured basic photo to begin with.</td>', 'Excellent post processing and a nicely seen and captured basic photo to begin with.', '2007-01-01 09:26:58.000000', NULL, 1),
(3167072, 442857, 30982, '<td valign="top">A gorgeous piece of art.  Not sure how the voters are receiving this as a "photograph" but I quite like it as graphic art.</td>', 'A gorgeous piece of art.  Not sure how the voters are receiving this as a "photograph" but I quite like it as graphic art.', '2007-01-01 09:28:21.000000', NULL, 1),
(3167076, 443599, 30982, '<td valign="top">I quite like the photograph but suspect you''re getting some DNMC comments.</td>', 'I quite like the photograph but suspect you''re getting some DNMC comments.', '2007-01-01 09:29:15.000000', NULL, 1),
(3167083, 442359, 30982, '<td valign="top">What a great find!  Processing is a bit on the strong side but works for this challenge.</td>', 'What a great find!  Processing is a bit on the strong side but works for this challenge.', '2007-01-01 09:33:53.000000', NULL, 1),
(3167085, 441885, 30982, '<td valign="top">Excellent.</td>', 'Excellent.', '2007-01-01 09:34:16.000000', NULL, 1),
