(3167089, 443440, 30982, '<td valign="top">So that''s what it looks like - neat!</td>', 'So that''s what it looks like - neat!', '2007-01-01 09:35:34.000000', NULL, 1),
(3167093, 443801, 30982, '<td valign="top">Nice colors, interesting shot.</td>', 'Nice colors, interesting shot.', '2007-01-01 09:36:20.000000', NULL, 1),
(3167098, 443490, 30982, '<td valign="top">Nice "natural" way to show a harsh environment.</td>', 'Nice "natural" way to show a harsh environment.', '2007-01-01 09:37:36.000000', NULL, 1),
(3167101, 443809, 30982, '<td valign="top">A surprisingly striking shot for something so "normal" - great detail.</td>', 'A surprisingly striking shot for something so "normal" - great detail.', '2007-01-01 09:38:37.000000', NULL, 1),
(3167106, 443038, 30982, '<td valign="top">Nifty idea - I like the one clerk who knows you''re taking the picture.  Fun to look at!</td>', 'Nifty idea - I like the one clerk who knows you''re taking the picture.  Fun to look at!', '2007-01-01 09:40:03.000000', NULL, 1),
(3167109, 443807, 30982, '<td valign="top">Nicely presented - harsh but strangely soothing.</td>', 'Nicely presented - harsh but strangely soothing.', '2007-01-01 09:40:37.000000', NULL, 1),
(3167110, 442808, 30982, '<td valign="top">Very creative interpretation!</td>', 'Very creative interpretation!', '2007-01-01 09:41:26.000000', NULL, 1),
(3167113, 443708, 30982, '<td valign="top">Sweet sweet shot.  Love the sun, the mist and the black of the lane.  Nicely composed, exposed, and presented.</td>', 'Sweet sweet shot.  Love the sun, the mist and the black of the lane.  Nicely composed, exposed, and presented.', '2007-01-01 09:41:52.000000', NULL, 1),
(3167123, 441839, 30982, '<td valign="top">Excellent for meeting the challenge - glad to see you followed through on your concept.  I like how you take us from a distance all the way in - put a face on the situation, so to speak.</td>', 'Excellent for meeting the challenge - glad to see you followed through on your concept.  I like how you take us from a distance all the way in - put a face on the situation, so to speak.', '2007-01-01 09:45:05.000000', NULL, 1),
(3167129, 442686, 30982, '<td valign="top">Perfect interpretation!  And great job with this - very well done and well edited!</td>', 'Perfect interpretation!  And great job with this - very well done and well edited!', '2007-01-01 09:46:07.000000', NULL, 1),
(3167143, 443396, 30982, '<td valign="top">Not sure I get the challenge tie-in, but I love the shot.</td>', 'Not sure I get the challenge tie-in, but I love the shot.', '2007-01-01 09:49:21.000000', NULL, 1),
(3167156, 443649, 16241, '<td valign="top">:))</td>', ':))', '2007-01-01 09:53:04.000000', NULL, 1),
