(3167492, 442429, 5436, '<td valign="top">I really like this shot. Just wish the smaller building on the left was not included or cropped in half.</td>', 'I really like this shot. Just wish the smaller building on the left was not included or cropped in half.', '2007-01-01 11:26:37.000000', NULL, 1),
(3167554, 443547, 5436, '<td valign="top">I like the photo alot but not the color of the frame.</td>', 'I like the photo alot but not the color of the frame.', '2007-01-01 11:55:58.000000', NULL, 1),
(3167581, 443547, 70375, '<td valign="top">OMG That poor book!!! :(</td>', 'OMG That poor book!!! :(', '2007-01-01 12:05:13.000000', NULL, 1),
(3167583, 443396, 70375, '<td valign="top">I am very interested to know how in the heck you did this!!! The colors are superb, the clarity is perfect!</td>', 'I am very interested to know how in the heck you did this!!! The colors are superb, the clarity is perfect!', '2007-01-01 12:06:11.000000', NULL, 1),
(3167590, 443636, 70375, '<td valign="top">I like the dead tree... adds depth... but I do feel you could have done more... it looks like an advanced edit entry ;) Still, lovely photograph!</td>', 'I like the dead tree... adds depth... but I do feel you could have done more... it looks like an advanced edit entry ;) Still, lovely photograph!', '2007-01-01 12:07:48.000000', NULL, 1),
