(3170581, 443276, 53243, '<td valign="top">The glare from the sun is the distraction, but it''s definitely a harsh environment.</td>', 'The glare from the sun is the distraction, but it''s definitely a harsh environment.', '2007-01-02 12:26:17.000000', NULL, 1),
