INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3171532, 443676, 38198, '<td valign="top">I like the sky and the sunset in the window, good colors. I think with the Expert Editing I would like to have seen the plywood removed and some thing else in it''s place. It takes away form the over look of distruction.</td>', 'I like the sky and the sunset in the window, good colors. I think with the Expert Editing I would like to have seen the plywood removed and some thing else in it''s place. It takes away form the over look of distruction.', '2007-01-02 16:27:54.000000', NULL, 1),
(3171546, 442842, 38198, '<td valign="top">I don''t truly feel that your subject is lying on this surface. That said I don''t beleave that is an over factor, I am voting expert editing more on an art bacis. The title is good and it fits the challenge. The sky is wonderful and the position of the subject gives and over all feeling of dispare, nice touch of the bare feet and dirt on subject. I like the darkness and the movement of the storm. Over all 9</td>', 'I don''t truly feel that your subject is lying on this surface. That said I don''t beleave that is an over factor, I am voting expert editing more on an art bacis. The title is good and it fits the challenge. The sky is wonderful and the position of the subject gives and over all feeling of dispare, nice touch of the bare feet and dirt on subject. I like the darkness and the movement of the storm. Over all 9', '2007-01-02 16:31:52.000000', NULL, 1),
