(3533175, 443649, 47274, '<td valign="top">haha love the expression!<br/>great job!!</td>', 'haha love the expression!great job!!', '2007-04-09 15:54:15.000000', NULL, 0),
(3549199, 443277, 63269, '<td valign="top">Bizzare, yet strikingly beautiful! This is an exremely unusual, interesting shot, it really makes the viewer look twice at it!</td>', 'Bizzare, yet strikingly beautiful! This is an exremely unusual, interesting shot, it really makes the viewer look twice at it!', '2007-04-15 12:54:26.000000', NULL, 0),
(3585892, 443625, 28742, '<td valign="top">Wow! How''d I miss this? Love it!</td>', 'Wow! How''d I miss this? Love it!', '2007-04-26 17:51:21.000000', NULL, 0),
(3664809, 443755, 76217, '<td valign="top">Good Composition...</td>', 'Good Composition...', '2007-05-18 22:36:06.000000', NULL, 0),
(3723257, 442112, 60862, '<td valign="top">Very powerful.  Well done!</td>', 'Very powerful.  Well done!', '2007-06-01 10:17:41.000000', NULL, 0),
(3791746, 443918, 63269, '<td valign="top">Fantastic, fabulous image.  I love the monotone... and the textures and details of the rocks are so perfectly contrasted by the  smooth water and the mist in the background. Superb shot.</td>', 'Fantastic, fabulous image.  I love the monotone... and the textures and details of the rocks are so perfectly contrasted by the  smooth water and the mist in the background. Superb shot.', '2007-06-16 17:18:23.000000', NULL, 0),
(3811544, 442112, 28710, '<td valign="top">A couple of things I noticed:<br/> <br/>#1 focus is good on the door. Soft on the child. This works perfectly for this shot... gives a bit of an ''off'' feeling to the child. Being underexposed is quite normal and natural for the ''other side'' of the light... This is not intended to be a beautifully lit portrait.<br/> <br/>#2 the insertion of the child into the shot is very well done. Needs a tiny bit of a feather or something around the head on the right side... there''s a bit of hue or something from the original pic left that gives a bit of ''cutout'' look.<br/> <br/>#3 a bit of a distraction in the top left quadrant in the flame, about a third of the way down near the edge... this is the only thing that gets you thinking about the background that would normally be around the door. Get rid of that and the illusion is complete.<br/> <br/>All in all a truly excellent work!<br/><br/><i>Message edited by author 2007-06-20 21:45:00.</i></td>', 'A couple of things I noticed: #1 focus is good on the door. Soft on the child. This works perfectly for this shot... gives a bit of an ''off'' feeling to the child. Being underexposed is quite normal and natural for the ''other side'' of the light... This is not intended to be a beautifully lit portrait. #2 the insertion of the child into the shot is very well done. Needs a tiny bit of a feather or something around the head on the right side... there''s a bit of hue or something from the original pic left that gives a bit of ''cutout'' look. #3 a bit of a distraction in the top left quadrant in the flame, about a third of the way down near the edge... this is the only thing that gets you thinking about the background that would normally be around the door. Get rid of that and the illusion is complete. All in all a truly excellent work!', '2007-06-20 22:42:26.000000', '2007-06-20 22:45:00.000000', 0),
(3826340, 443755, 55330, '<td valign="top">What does this have to do with Golf????</td>', 'What does this have to do with Golf????', '2007-06-24 01:19:42.000000', NULL, 0),
(3869002, 442429, 51538, '<td valign="top">Comment made long after the challenge:  You''re one of the few people using the Canon 135mm f/2.0 on DPC.  I tried it out recently on a 5D and like that lens a lot.  It is perfectly crisp with nice depth of field control.  I was wondering just how much usage you get out of yours?  Now and again? or a lot?  Living in a big city, my needs might well be quite different from yours.  But I am curious to know, if you have time to respond.  Thanks in advance.</td>', 'Comment made long after the challenge:  You''re one of the few people using the Canon 135mm f/2.0 on DPC.  I tried it out recently on a 5D and like that lens a lot.  It is perfectly crisp with nice depth of field control.  I was wondering just how much usage you get out of yours?  Now and again? or a lot?  Living in a big city, my needs might well be quite different from yours.  But I am curious to know, if you have time to respond.  Thanks in advance.', '2007-07-04 20:25:33.000000', NULL, 0),
(3902517, 443441, 81291, '<td valign="top">Wow, this is a great shot<br/>i really like it,<br/>the colours are great,<br/>and the lighting is perfect.<br/> <br/>this is one of my favorites,<br/>good job<br/></td>', 'Wow, this is a great shoti really like it,the colours are great,and the lighting is perfect. this is one of my favorites,good job', '2007-07-14 09:55:23.000000', NULL, 0),
