(4041194, 441885, 36371, '<td valign="top">Puts MY life into perspective. Thanks so much for sharing this story. And I am glad that you overcame your fears to reach out to them. I''m sure they loved their photos.</td>', 'Puts MY life into perspective. Thanks so much for sharing this story. And I am glad that you overcame your fears to reach out to them. I''m sure they loved their photos.', '2007-08-30 09:48:15.000000', NULL, 0),
(4323916, 443441, 63269, '<td valign="top">I like all the textures and the beautiful light you''ve captured. nice!</td>', 'I like all the textures and the beautiful light you''ve captured. nice!', '2007-12-19 16:19:01.000000', NULL, 0),
